//! Terrain of every state (`assets/map/terrain.ron`, generated by `bf-mapgen terrain`): the
//! shares of mountain and marsh, the mean elevation when a grid gives it, and the big rivers on
//! the borders between neighbouring states. Forest comes from `land.ron`, towns from the urban
//! population of `population.ron`; [`crate::war::state_terrain`] puts them together into the mix
//! the land step reads. Method and sources: `docs/map-pipeline.pt-BR.md`, "Terreno".

use laplace_schelling::Fixed;
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct TerrainFile {
    pub meta: TerrainMeta,
    /// One row per state, in id order.
    pub states: Vec<StateTerrain>,
    /// Pairs of neighbouring states whose border runs along a big river.
    pub borders: Vec<RiverBorder>,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct TerrainMeta {
    pub sources: Vec<String>,
    /// Local relief (standard deviation of the elevation, metres) from which a cell counts as
    /// mountain.
    pub mountain_relief_m: u16,
    /// Natural Earth scale rank up to which a river counts as big.
    pub river_max_scalerank: u8,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct StateTerrain {
    /// State id in `provinces.ron`.
    pub state: u16,
    pub key: String,
    /// Share of the state's land that is mountain, per mille.
    pub mountain: u16,
    /// Share of the state's land that is marsh, per mille.
    pub marsh: u16,
    /// Mean elevation of the state's land, in metres; `None` for a state too small for the grid.
    #[serde(default)]
    pub elevation_m: Option<i32>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct RiverBorder {
    /// The two states, `a < b`.
    pub a: u16,
    pub b: u16,
    /// Pixel edges of their common border.
    pub border: u32,
    /// Of those, the ones within a pixel of a big river.
    pub river: u32,
    /// The river met most along the border.
    pub name: String,
}

impl TerrainFile {
    pub fn state(&self, id: u16) -> Option<&StateTerrain> {
        self.states.get(id as usize - 1).filter(|s| s.state == id)
    }

    /// Share of the border between two states that runs along a big river, 0 to 1. Only the
    /// border counts: a river inside a state waits for fronts with positions inside it.
    pub fn river_share(&self, a: u16, b: u16) -> Fixed {
        let (a, b) = (a.min(b), a.max(b));
        self.borders
            .iter()
            .find(|r| r.a == a && r.b == b)
            .filter(|r| r.border > 0)
            .map_or(Fixed::ZERO, |r| {
                Fixed::from_ratio(r.river.min(r.border) as i64, r.border as i64)
            })
    }

    pub fn river_name(&self, a: u16, b: u16) -> Option<&str> {
        let (a, b) = (a.min(b), a.max(b));
        self.borders
            .iter()
            .find(|r| r.a == a && r.b == b)
            .map(|r| r.name.as_str())
    }
}
